import {describe,expect,it} from "vitest";import {isEditableKeyboardTarget} from "../src/app/googDevice/isEditableKeyboardTarget";
describe("isEditableKeyboardTarget",()=>{it("recognizes nested elements inside editable controls",()=>{document.body.innerHTML='<textarea><span></span></textarea><div contenteditable="true"><b id="nested"></b></div>';expect(isEditableKeyboardTarget(document.querySelector("textarea"))).toBe(true);expect(isEditableKeyboardTarget(document.querySelector("#nested"))).toBe(true)});it("does not suppress device keyboard capture for ordinary stream elements",()=>{document.body.innerHTML='<div class="stream"><canvas></canvas></div><div contenteditable="false" id="disabled"></div>';expect(isEditableKeyboardTarget(document.querySelector("canvas"))).toBe(false);expect(isEditableKeyboardTarget(document.querySelector("#disabled"))).toBe(false)})});
